<?php require_once __DIR__.'/includes/auth.php';$u=require_login();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='all')db()->prepare('UPDATE notifications SET is_read=1 WHERE user_id=?')->execute([$u['id']]);else{$id=(int)($_POST['id']??0);db()->prepare('UPDATE notifications SET is_read=1 WHERE id=? AND user_id=?')->execute([$id,$u['id']]);}redirect('notifications.php');}$q=db()->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 100');$q->execute([$u['id']]);$items=$q->fetchAll();$pageTitle='Notifications — LocalConnect';require __DIR__.'/includes/header.php';?><div class="container py-5" style="max-width:900px"><div class="d-flex justify-content-between align-items-center mb-4"><h1 class="fw-bold mb-0">Notifications</h1><?php if(unread_notification_count((int)$u['id'])):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="all"><button class="btn btn-outline-primary">Mark all read</button></form><?php endif;?></div><div class="soft-card overflow-hidden"><?php foreach($items as $x):?><div class="p-4 border-bottom <?=$x['is_read']?'':'bg-light'?>"><div class="d-flex justify-content-between gap-3"><div><strong><?=e($x['title'])?></strong><?php if(!$x['is_read']):?><span class="badge bg-primary ms-2">New</span><?php endif;?><p class="mb-1 mt-1"><?=e($x['message'])?></p><small class="text-muted"><?=e(date('d M Y, h:i A',strtotime($x['created_at'])))?></small><?php if($x['link']):?><div class="mt-2"><a href="<?=e(base_url($x['link']))?>">Open</a></div><?php endif;?></div><?php if(!$x['is_read']):?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$x['id']?>"><button class="btn btn-sm btn-outline-secondary">Mark read</button></form><?php endif;?></div></div><?php endforeach;?><?php if(!$items):?><div class="p-5 text-center"><h4>No notifications yet.</h4><p class="text-muted mb-0">Request and review updates will appear here.</p></div><?php endif;?></div></div><?php require __DIR__.'/includes/footer.php';?>
